    "official_text": "Art. 1º São atividades privativas de advocacia:\nI - a postulação a qualquer órgão do Poder Judiciário e aos juizados especiais;\nII - as atividades de consultoria, assessoria e direção jurídicas.\n§ 1º Não se inclui na atividade privativa a impetração de habeas corpus em qualquer tribunal ou tribunal de justiça.\n§ 2º Os atos e contratos constitutivos de pessoas jurídicas só podem ser admitidos a registro, nos órgãos competentes, quando visados por advogados (ressalvadas as ME/EPP da Lei Complementar 123/06).\n§ 3º É vedada a divulgação de advocacia em conjunto com outra atividade.",
