    "title": "Do Rol de Impedimentos ao Exercício da Advocacia (Proibição Parcial)",
    "hierarchy": {
      "title_num": "Título I - Capítulo VII: Das Incompatibilidades e Impedimentos",
      "chapter_num": "Incompatibilidade Total (Art. 28: Juízes, MP, Policiais, Militares e Chefes do Executivo) vs. Impedimento Parcial (Art. 30: Servidores e Parlamentares)"
    },
    "category": "Incompatibilidades e Impedimentos",
    "isOabFocus": true,
    "source": {
      "name": "Presidência da República - Planalto",
      "url": "https://www.planalto.gov.br/ccivil_03/leis/l8906.htm#art30",
      "last_checked_at": "2026-08-15T00:00:00Z",
      "version": "1.0.0"
    },
    "official_text": "Art. 30. São impedidos de exercer a advocacia:\nI - os servidores da administração direta, indireta e fundacional, contra a Fazenda Pública que os remunere ou à qual seja vinculada a entidade empregadora;\nII - os membros do Poder Legislativo, em seus diferentes níveis, contra ou a favor das pessoas jurídicas de direito público, empresas públicas, sociedades de economia mista, fundações públicas, entidades paraestatais ou empresas concessionárias ou permissionárias de serviço público.\nParágrafo único. Não se incluem nas hipóteses do inciso I os docentes dos cursos jurídicos.",
    "content": [
      {
        "id": "eoab-art30-caput",
        "type": "caput",
        "text": "Art. 30. São impedidos de exercer a advocacia:\nI - os servidores da administração direta, indireta e fundacional, contra a Fazenda Pública que os remunere ou à qual seja vinculada a entidade empregadora;\nII - os membros do Poder Legislativo, em seus diferentes níveis, contra ou a favor das pessoas jurídicas de direito público, empresas públicas, sociedades de economia mista, fundações públicas, entidades paraestatais ou empresas concessionárias ou permissionárias de serviço público.\nParágrafo único. Não se incluem nas hipóteses do inciso I os docentes dos cursos jurídicos.",
        "speechText": "Art. 30. São impedidos de exercer a advocacia: I - os servidores da administração direta, indireta e fundacional, contra a Fazenda Pública que os remunere ou à qual seja vinculada a entidade empregadora; II - os membros do Poder Legislativo, em seus diferentes níveis, contra ou a favor das pessoas jurídicas de direito público, empresas públicas, sociedades de economia mista, fundações públicas, entidades paraestatais ou empresas concessionárias ou permissionárias de serviço público. Parágrafo único. Não se incluem nas hipóteses do inciso I os docentes dos cursos jurídicos."
      }
    ],
    "professor_mode": {
      "simple_explanation": "Impedimento = PROIBIÇÃO PARCIAL de advogar. 1) Servidores públicos em geral: podem advogar em quase tudo, EXCETO contra a pessoa jurídica de direito público que paga seus salários (exceção: professores universitários de Direito podem advogar livremente contra a Fazenda); 2) Parlamentares (Deputados, Senadores, Vereadores que não integrem a Mesa): não podem advogar a favor nem contra a Administração Pública ou concessionárias.",
      "summary": "Impedimento (proibição parcial): servidores públicos não advogam contra a Fazenda que os remunera; parlamentares não advogam contra/a favor do poder público.",
      "practical_example": "Aplicação prática do Art. 30: aplicação cogente na prática forense, processos disciplinares no TED e prerrogativas profissionais perante autoridades.",
      "exam_tip": "Atenção: O Art. 30 possui altíssima incidência nas 8 questões de Ética Profissional da 1ª Fase do Exame de Ordem (OAB).",
      "legal_terms": [
        "EOAB",
        "Incompatibilidades e Impedimentos",
        "Ética Profissional",
        "Prerrogativas do Advogado"
      ],
      "speechText": "Modo Professor sobre o Artigo 30 do Estatuto da Advocacia e da OAB: Impedimento = PROIBIÇÃO PARCIAL de advogar. 1) Servidores públicos em geral: podem advogar em quase tudo, EXCETO contra a pessoa jurídica de direito público que paga seus salários (exceção: professores universitários de Direito podem advogar livremente contra a Fazenda); 2) Parlamentares (Deputados, Senadores, Vereadores que não integrem a Mesa): não podem advogar a favor nem contra a Administração Pública ou concessionárias."
    }
